insert into public.question_versions
  (id, question_id, version, state, text, explanation, category_id, country_scope, difficulty, age_rating, tags, language, sources, content_hash, published_at)
values
  ('640a66c4-3d42-5dda-8d75-4e141fb4e1e4', '7968b3c9-1a63-5841-87cd-9e60c6e458e3', 1, 'approved', 'Ngũgĩ wa Thiong’o, author of “Weep Not, Child”, was from which country?', 'Ngũgĩ wa Thiong’o was a Kenyan novelist who later championed writing in Gĩkũyũ.', 'arts', array['KE']::text[], 'medium', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: Ngũgĩ wa Thiongʼo","url":"https://en.wikipedia.org/wiki/Ng%C5%A9g%C4%A9_wa_Thiong%CA%BCo"}]'::jsonb, '978cfd3c6f0366e571df724c208d2a2aa40348cfe66953089662b5a0938afba4', now()),
  ('90af8fe0-ff4b-5685-afcb-ef5719286c10', 'e3bd42f7-bcd8-5244-8264-4f19473a27e6', 1, 'approved', 'Highlife music originated in which country?', 'Highlife began in Ghana in the early 20th century, blending local rhythms with Western instruments.', 'arts', array['GH']::text[], 'medium', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: Highlife","url":"https://en.wikipedia.org/wiki/Highlife"}]'::jsonb, 'f50ab3a83bb0c369a0e1c5c33e78d177808cb62038cb3957f2e0b64d50abec0c', now()),
  ('4a81aaf8-69f0-509f-8d97-d7eb4f9da44a', '4a6aa4a2-82b0-5748-9849-77013cc51ac3', 1, 'approved', 'Which Egyptian singer was known as “Kawkab al-Sharq”, the Star of the East?', 'Umm Kulthum was one of the Arab world’s most celebrated singers from the 1920s to the 1970s.', 'arts', array['EG']::text[], 'hard', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: Umm Kulthum","url":"https://en.wikipedia.org/wiki/Umm_Kulthum"}]'::jsonb, '2466d3c6f6f79c981af9b08a6bb6db8b253d2e366df50c0ac576d2577b5e3253', now()),
  ('de9973a4-0185-5899-899a-d1f552d62344', 'e5f56e1d-ee0d-5826-beef-1164716fe132', 1, 'approved', 'Which Egyptian author won the Nobel Prize in Literature in 1988?', 'Naguib Mahfouz, author of the Cairo Trilogy, was the first Arabic-language writer to win the Nobel Prize in Literature.', 'arts', array['EG']::text[], 'hard', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: Naguib Mahfouz","url":"https://en.wikipedia.org/wiki/Naguib_Mahfouz"}]'::jsonb, 'be7865fff7d04c9dcb5efa25722915a8906c1d5712b3cce837d8c7fb53af05c7', now()),
  ('1578efd0-8dd5-5fe3-9395-d1f6596c386a', '8b4ee972-e48e-5e5f-9c6b-61abd333aef8', 1, 'approved', 'The Benin Bronzes were made in the Kingdom of Benin, which is in which present-day country?', 'The Kingdom of Benin was centred on Benin City in southern Nigeria. It is not the modern Republic of Benin.', 'arts', array['NG']::text[], 'hard', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: Benin Bronzes","url":"https://en.wikipedia.org/wiki/Benin_Bronzes"}]'::jsonb, '9bb785a428d930d740b28a8b05970012b4b503fd3edab857305b2788cf33c621', now()),
  ('4d1826e2-3035-5960-8c40-10c673631958', 'c8ebbd3e-a62e-574a-b172-c7a9c4fddcdd', 1, 'approved', 'Which novel by Chimamanda Ngozi Adichie is set during the Nigerian Civil War?', '“Half of a Yellow Sun” (2006) follows several characters through the Biafran War. “The Famished Road” is by Ben Okri.', 'arts', array['NG']::text[], 'hard', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: Half of a Yellow Sun","url":"https://en.wikipedia.org/wiki/Half_of_a_Yellow_Sun"}]'::jsonb, '014e57b7f861ac102b4e52011da873a06f9a603df897de71301074e210ef927b', now()),
  ('a675b9e9-8f60-5773-bacd-82afb2762054', 'd87b33b2-fef2-5ab5-a529-e9b0ec8b9d12', 1, 'approved', 'Mohamed Salah plays international football for which country?', 'Mohamed Salah is Egypt’s star forward and one of Africa’s best-known footballers.', 'sports', array['EG']::text[], 'easy', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: Mohamed Salah","url":"https://en.wikipedia.org/wiki/Mohamed_Salah"}]'::jsonb, '4100a40d4ac3686b6f3a418f67c85a0967bf68c6ff2f7853eb4d0fda91f986d0', now()),
  ('57f89188-f0ba-5e0e-b7c1-df188ec6fcec', '53a4731e-4d8e-56ec-a5a7-19be02a820bb', 1, 'approved', 'In 2022, which country became the first African team to reach a FIFA World Cup semi-final?', 'Morocco reached the semi-finals in Qatar in 2022, beating Spain and Portugal on the way.', 'sports', array['MA']::text[], 'easy', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: Morocco national football team","url":"https://en.wikipedia.org/wiki/Morocco_national_football_team"}]'::jsonb, 'ca2f6edc78d86591c16061fd92ab0855aae245d1057b51680a893c9801d68bc8', now()),
  ('7a77a957-c8b7-59ef-98e9-747d685e3fef', 'dc1d6507-068a-5202-8e94-e2d8de3f45d0', 1, 'approved', 'Marathon great Eliud Kipchoge is from which country?', 'Eliud Kipchoge, a two-time Olympic marathon champion, is from Kenya.', 'sports', array['KE']::text[], 'easy', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: Eliud Kipchoge","url":"https://en.wikipedia.org/wiki/Eliud_Kipchoge"}]'::jsonb, '6515885d5a80f50b3c0b505884019a761b64cd7912432903b8b4ecf620e5b11a', now()),
  ('e25630ae-4e72-5387-ab93-04eea775a955', '6d2d948e-8c86-5dac-97b0-e93a968e9030', 1, 'approved', 'Which country’s national rugby team is nicknamed the Springboks?', 'The Springboks are South Africa’s national rugby union team and multiple Rugby World Cup winners.', 'sports', array['ZA']::text[], 'easy', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: South Africa national rugby union team","url":"https://en.wikipedia.org/wiki/South_Africa_national_rugby_union_team"}]'::jsonb, '8e94b1f926c3029037ce10159830a6882984344fcb0a5f6ae286d7c4f459f8bb', now()),
  ('4a52525f-011c-59dd-832c-681102e1f579', '66a887df-1208-540a-a54c-28a32e224bd2', 1, 'approved', 'Which country won the 2023 Africa Cup of Nations, played in early 2024?', 'Host nation Côte d’Ivoire beat Nigeria 2–1 in the final in Abidjan in February 2024.', 'sports', array['CI']::text[], 'medium', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: 2023 Africa Cup of Nations","url":"https://en.wikipedia.org/wiki/2023_Africa_Cup_of_Nations"}]'::jsonb, '4d31dfcaed7be68780cdec52e751b7181b8149a5e0ce36151236c3cb35ea2344', now()),
  ('f26a51c7-81b3-5749-a856-003d8e5a4574', '2faa1fdf-2482-5161-b72f-62ae75c11b53', 1, 'approved', 'Which Ethiopian runner won the 1960 Olympic marathon running barefoot?', 'Abebe Bikila won the Rome 1960 marathon barefoot, becoming Ethiopia’s first Olympic champion.', 'sports', array['ET']::text[], 'medium', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: Abebe Bikila","url":"https://en.wikipedia.org/wiki/Abebe_Bikila"}]'::jsonb, '0ba5384f06da51b882e83e7a85137535d37ece2d2bb114e3dd9d745f91d350f0', now()),
  ('5a9bd31a-e23d-5c75-b770-83aa13fa33e1', '2394859e-cb9d-5462-9c2a-50d1155bc096', 1, 'approved', 'Which country has won the most Africa Cup of Nations titles?', 'Egypt has won the Africa Cup of Nations seven times, more than any other country.', 'sports', array['EG']::text[], 'medium', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: Africa Cup of Nations","url":"https://en.wikipedia.org/wiki/Africa_Cup_of_Nations"}]'::jsonb, '2037d2b1355d902f533157376c837153aa311022b516a8967960f89235aa902d', now()),
  ('847a97fa-72cc-5dc3-b9f7-b3b9ed6a5973', '3a2ac5eb-00b6-5f67-b312-b1cf27da4a93', 1, 'approved', 'George Weah, the only African to win the Ballon d’Or, later became president of which country?', 'George Weah won the Ballon d’Or in 1995 and served as President of Liberia from 2018 to 2024.', 'sports', array['LR']::text[], 'medium', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: George Weah","url":"https://en.wikipedia.org/wiki/George_Weah"}]'::jsonb, '7b4093b2a2d7d12b90121f6108070989259b852360c093f64a4f95e9727200f9', now()),
  ('3aa7d8c6-f690-5653-9e20-37ba115d1831', '6c10f1ee-9e3f-5418-a275-6708004459bb', 1, 'approved', 'Who is the all-time top scorer in Africa Cup of Nations history?', 'Cameroon’s Samuel Eto’o scored 18 goals at the Africa Cup of Nations, the tournament record.', 'sports', array['CM']::text[], 'hard', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: Samuel Eto''o","url":"https://en.wikipedia.org/wiki/Samuel_Eto%27o"}]'::jsonb, '449be8975c78cd68dc49d2fa3fb83f78095b466e3fd9bd4761977dab8235efc0', now()),
  ('3fee3175-39b3-5d2f-9373-13959757787d', '146f8247-384a-58a0-a245-f2a9c83d95c7', 1, 'approved', 'Who captained South Africa to victory at the 1995 Rugby World Cup on home soil?', 'Francois Pienaar received the trophy from President Nelson Mandela at Ellis Park in Johannesburg.', 'sports', array['ZA']::text[], 'hard', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: 1995 Rugby World Cup final","url":"https://en.wikipedia.org/wiki/1995_Rugby_World_Cup_final"}]'::jsonb, '23e91b187b92efe3f0ffe143a3a2d52ab2e262041d7195133801e2d467943d1c', now()),
  ('396b29df-03a7-5c47-b7a7-c31b6b6b495f', '8b7c0591-6773-5490-a14f-c48b169615b8', 1, 'approved', 'Which Kenyan runner set the men’s 800 m world record of 1:40.91 at the 2012 Olympics?', 'David Rudisha ran 1:40.91 to win the London 2012 Olympic 800 m final, the first run under 1:41.', 'sports', array['KE']::text[], 'hard', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: David Rudisha","url":"https://en.wikipedia.org/wiki/David_Rudisha"}]'::jsonb, '9fd0385ec18a4e2170dea008d732305aeb98d63ae5da1441efcc118f54845249', now()),
  ('5eea7899-ec86-564b-a2e8-9211a0dea3b5', 'bd25f8a5-2d8f-5bd9-a322-107d54f1aba5', 1, 'approved', 'Which is the fastest land animal, found on Africa’s savannahs?', 'Cheetahs can sprint at around 100 km/h over short distances.', 'science', array['AFRICA']::text[], 'easy', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: Cheetah","url":"https://en.wikipedia.org/wiki/Cheetah"}]'::jsonb, 'd56a6827e6644c2ab315a10f918b7c28cfd96f77ea695cc6b053766f962bad18', now()),
  ('e589d4ad-0d5f-5d67-a98b-9edd6164d6b6', 'ad7470cc-6437-5721-af71-2c280084a1f6', 1, 'approved', 'The “Big Five” are the lion, leopard, elephant, buffalo and which other animal?', 'The term “Big Five” first came from hunting; it now names the five animals that safari-goers most want to see.', 'science', array['AFRICA']::text[], 'easy', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: Big five game","url":"https://en.wikipedia.org/wiki/Big_five_game"}]'::jsonb, '2076eefe522e6f810066b9e36d5075b571f1ae5fba96e6b759cbd9cf58506041', now()),
  ('1c71992e-5ea7-593c-a7bd-3ba798da8824', 'b3d1ef41-ca93-5be4-93b7-b1fe061910a7', 1, 'approved', 'Lemurs are native to which island country?', 'Lemurs evolved in isolation on Madagascar, home to over 100 lemur species and subspecies.', 'science', array['MG']::text[], 'easy', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: Lemur","url":"https://en.wikipedia.org/wiki/Lemur"}]'::jsonb, 'd335cd52bbbc53239cb0e3f34975f40c529795c4a3a00394e8e104c244df9374', now()),
  ('c2a63dcc-c7aa-5413-bbb9-cbda7ae71dec', '656dc0c4-bf3b-5c78-9417-871907705b7c', 1, 'approved', 'Which South African surgeon performed the world’s first human heart transplant in 1967?', 'Christiaan Barnard led the first human-to-human heart transplant at Groote Schuur Hospital, Cape Town, in December 1967.', 'science', array['ZA']::text[], 'medium', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: Christiaan Barnard","url":"https://en.wikipedia.org/wiki/Christiaan_Barnard"}]'::jsonb, 'd9b5ea52f4a97264a80b0bccd7a470ccb18292ef9d5811e7449800f7134d43fe', now()),
  ('c64594f2-fe17-52bc-b45f-53a0b5a8fb84', '469a27bc-0a3d-5be7-b64f-da3e4e8aea8d', 1, 'approved', 'Which Kenyan environmentalist founded the Green Belt Movement and won the 2004 Nobel Peace Prize?', 'Wangari Maathai’s Green Belt Movement has planted tens of millions of trees. She was the first African woman to win the Nobel Peace Prize.', 'science', array['KE']::text[], 'medium', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: Wangari Maathai","url":"https://en.wikipedia.org/wiki/Wangari_Maathai"}]'::jsonb, 'b240e55a75de6d6333caf48cd935bc56d7267ca62c5d62f06d20b69a5f4e7dc5', now()),
  ('448f971c-74ff-5de6-bf8f-f444e730333a', '4ea0c32f-6a32-518d-b169-83a783e44620', 1, 'approved', 'The fossil skeleton “Lucy” (Australopithecus afarensis) was discovered in which country?', 'Lucy was found at Hadar in Ethiopia’s Afar region in 1974 and is about 3.2 million years old.', 'science', array['ET']::text[], 'medium', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: Lucy (Australopithecus)","url":"https://en.wikipedia.org/wiki/Lucy_(Australopithecus)"}]'::jsonb, '9e921181dd9273820d19e9fc16e9ed4841f042ebeaab07e202651094777acd21', now()),
  ('33def7b9-1152-5225-935e-a4ac71f3f568', 'ca6ba5ed-82a1-5845-8a54-e4a5e0e08e1b', 1, 'approved', 'Mountain gorillas live in the Virunga Mountains, shared by Rwanda, Uganda and which other country?', 'The Virunga volcanoes straddle Rwanda, Uganda and DR Congo; mountain gorillas also live in Uganda’s Bwindi forest.', 'science', array['RW', 'UG', 'CD']::text[], 'medium', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: Mountain gorilla","url":"https://en.wikipedia.org/wiki/Mountain_gorilla"}]'::jsonb, 'e0ba4b85fe1bb2105eae84a6c2a29de7bde767d005864422ac332bdb0bb45ef2', now()),
  ('dec8efde-b645-5169-ba24-9cee7b985650', 'ad5fdb00-0573-5d9b-a598-7bc93c426a57', 1, 'approved', 'Which African river is the deepest recorded river in the world?', 'Parts of the lower Congo River are over 220 m deep, the greatest depth recorded for any river.', 'science', array['CD', 'CG']::text[], 'hard', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: Congo River","url":"https://en.wikipedia.org/wiki/Congo_River"}]'::jsonb, '4a81a2a020c0663cd19b08113278b460b3c3926acc9cd21dfc42efa5305ab187', now())
